class Solution:
    def findValidPair(self, s: str) -> str:
        freq = [0] * 10
        for ch in s:
            freq[ord(ch) - ord('0')] += 1

        valid_digit = [False] * 10
        for d in range(1, 10):
            if freq[d] == d:
                valid_digit[d] = True

        for i in range(len(s) - 1):
            a = ord(s[i]) - ord('0')
            b = ord(s[i + 1]) - ord('0')
            if a != b and valid_digit[a] and valid_digit[b]:
                return s[i:i + 2]
        return ""

