class Solution:
    def zigzagTraversal(self, grid: List[List[int]]) -> List[int]:
        result = []
        n = len(grid)
        m = len(grid[0])
        index = 0

        for i in range(n):
            cols = range(m) if i % 2 == 0 else range(m - 1, -1, -1)
            for j in cols:
                if index % 2 == 0:
                    result.append(grid[i][j])
                index += 1

        return result

