class Solution:
    def largestInteger(self, nums: List[int], k: int) -> int:
        n = len(nums)
        count = {}
        for start in range(n - k + 1):
            seen = {}
            for j in range(k):
                x = nums[start + j]
                seen[x] = seen.get(x, 0) + 1
            for x in seen:
                count[x] = count.get(x, 0) + 1
        ans = -1
        for x, c in count.items():
            if c == 1:
                if x > ans:
                    ans = x
        return ans

