class Solution:
    def longestPalindromicSubsequence(self, s: str, k: int) -> int:
        MOD = 26
        dist = [[0] * MOD for _ in range(MOD)]
        for i in range(MOD):
            for j in range(MOD):
                diff = abs(i - j)
                dist[i][j] = min(diff, MOD - diff)

        pair_cost = [[0] * MOD for _ in range(MOD)]
        for i in range(MOD):
            for j in range(MOD):
                best_cost = 10 ** 9
                for t in range(MOD):
                    val = dist[i][t] + dist[j][t]
                    if val < best_cost:
                        best_cost = val
                pair_cost[i][j] = best_cost

        n = len(s)
        dp = [[[0] * (k + 1) for _ in range(n)] for _ in range(n)]
        for i in range(n):
            dp[i][i] = [1] * (k + 1)

        for length in range(2, n + 1):
            for l in range(0, n - length + 1):
                r = l + length - 1
                a = ord(s[l]) - ord('a')
                b = ord(s[r]) - ord('a')
                c = pair_cost[a][b]

                skip_left = dp[l + 1][r]
                skip_right = dp[l][r - 1]
                inner = dp[l + 1][r - 1]

                best = [0] * (k + 1)
                for budget in range(k + 1):
                    val = skip_left[budget]
                    if skip_right[budget] > val:
                        val = skip_right[budget]
                    if c <= budget:
                        cand = 2 + inner[budget - c]
                        if cand > val:
                            val = cand
                    best[budget] = val
                dp[l][r] = best

        return dp[0][n - 1][k]

