class Solution:
    def maxSum(self, nums: List[int], k: int, m: int) -> int:
        n = len(nums)
        pref = [0] * (n + 1)
        for i in range(n):
            pref[i + 1] = pref[i] + nums[i]

        NEG = float('-inf')

        # B_prev[i] = maximum sum of (j-1) subarrays inside nums[:i]
        # For j = 1, B_0[i] = 0 for all i.
        B_prev = [0] * (n + 1)

        for j in range(1, k + 1):
            # F[e] = maximum sum of j subarrays whose last one ends at e
            F = [NEG] * n
            run = NEG
            s = 0
            for e in range(n):
                limit = e - m + 1  # current subarray start s <= e - m + 1
                while s <= limit:
                    val = B_prev[s] - pref[s]
                    if val > run:
                        run = val
                    s += 1
                if run != NEG:
                    F[e] = pref[e + 1] + run

            # B_cur[i] = maximum sum of j subarrays inside nums[:i]
            B_cur = [NEG] * (n + 1)
            cur = NEG
            for i in range(1, n + 1):
                if F[i - 1] > cur:
                    cur = F[i - 1]
                B_cur[i] = cur

            B_prev = B_cur

        return int(B_prev[n])

