class Solution:
    def minMaxSubarraySum(self, nums: List[int], k: int) -> int:
        n = len(nums)

        prev_ge = [-1] * n
        stack = []
        for i in range(n):
            while stack and nums[stack[-1]] < nums[i]:
                stack.pop()
            if stack:
                prev_ge[i] = stack[-1]
            stack.append(i)

        next_gt = [n] * n
        stack = []
        for i in range(n - 1, -1, -1):
            while stack and nums[stack[-1]] <= nums[i]:
                stack.pop()
            if stack:
                next_gt[i] = stack[-1]
            stack.append(i)

        prev_le = [-1] * n
        stack = []
        for i in range(n):
            while stack and nums[stack[-1]] > nums[i]:
                stack.pop()
            if stack:
                prev_le[i] = stack[-1]
            stack.append(i)

        next_lt = [n] * n
        stack = []
        for i in range(n - 1, -1, -1):
            while stack and nums[stack[-1]] >= nums[i]:
                stack.pop()
            if stack:
                next_lt[i] = stack[-1]
            stack.append(i)

        def count(a: int, b: int) -> int:
            p = a if a < k else k
            if b >= k:
                return p * k - p * (p - 1) // 2
            m0 = k - b + 1
            if p < m0:
                m0 = p
            sum_b = b * m0
            tail = (p - m0) * k - (p * (p - 1) // 2 - m0 * (m0 - 1) // 2)
            return sum_b + tail

        total = 0
        for i in range(n):
            a = i - prev_ge[i]
            b = next_gt[i] - i
            total += nums[i] * count(a, b)

            a = i - prev_le[i]
            b = next_lt[i] - i
            total += nums[i] * count(a, b)

        return total
